const crypto = require('crypto');

const inputData = $input.first().json;
const headers = inputData.headers || {};
const secret = (typeof $env !== 'undefined' && $env.N8N_PASSWORD_RESET_HMAC_SECRET) || (typeof process !== 'undefined' && process.env && process.env.N8N_PASSWORD_RESET_HMAC_SECRET) || '';

const receivedSignature = headers['x-sportcomplex-signature'] || headers['X-SportComplex-Signature'] || '';

let rawPayload = '';
let parsedPayload = null;

let rawFromBinary = null;
try {
  if ($input.first().binary && $input.first().binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    rawFromBinary = buf.toString('utf8');
  }
} catch (e) {
  rawFromBinary = null;
}

if (rawFromBinary) {
  rawPayload = rawFromBinary;
  try {
    parsedPayload = JSON.parse(rawFromBinary);
  } catch (e) {
    parsedPayload = inputData.body;
  }
} else if (inputData.rawBody) {
  rawPayload = inputData.rawBody;
  try {
    parsedPayload = JSON.parse(inputData.rawBody);
  } catch (e) {
    parsedPayload = inputData.body;
  }
} else {
  rawPayload = typeof inputData.body === 'string' ? inputData.body : JSON.stringify(inputData.body);
  parsedPayload = typeof inputData.body === 'string' ? JSON.parse(inputData.body) : inputData.body;
}

let isValid = false;
if (secret && receivedSignature) {
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(rawPayload);
  const calculatedSignature = `sha256=${hmac.digest('hex')}`;
  const receivedBuf = Buffer.from(String(receivedSignature));
  const calculatedBuf = Buffer.from(calculatedSignature);
  if (receivedBuf.length === calculatedBuf.length) {
    isValid = crypto.timingSafeEqual(receivedBuf, calculatedBuf);
  }
} else if (!secret) {
  isValid = true;
}

return [
  {
    json: {
      isValid,
      payload: parsedPayload
    }
  }
];

